--
-- Table structure for table `emp_detail`
--

DROP TABLE IF EXISTS `emp_detail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `emp_detail` (
  `employee_id` bigint unsigned NOT NULL COMMENT 'PK & ref ke tmmst.m_emp.employee_id (FK dijaga app)',
  `gender` tinyint unsigned DEFAULT NULL,
  `birth_date` date DEFAULT NULL,
  `hire_date` date DEFAULT NULL,
  `resign_date` date DEFAULT NULL,
  `retire_date` date DEFAULT NULL,
  `emp_level` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `religion` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `marital_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone_number` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `photo_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `current_department_id` bigint unsigned DEFAULT NULL COMMENT 'ref tmmst.org_department (app)',
  `current_section_id` bigint unsigned DEFAULT NULL COMMENT 'ref tmmst.org_section (app)',
  `current_position_id` bigint unsigned DEFAULT NULL COMMENT 'ref emp_position (app)',
  `stat_confirm` tinyint unsigned DEFAULT '0',
  `create_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `update_log` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `create_by` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `update_by` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`employee_id`) USING BTREE,
  KEY `idx_dept` (`current_department_id`) USING BTREE,
  KEY `idx_section` (`current_section_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Employee employment detail (domain HR)';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `emp_detail`
--

LOCK TABLES `emp_detail` WRITE;
/*!40000 ALTER TABLE `emp_detail` DISABLE KEYS */;
