/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_emp_detail_check_master` BEFORE INSERT ON `emp_detail` FOR EACH ROW BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM tmmst.m_emp WHERE employee_id = NEW.employee_id
    ) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'employee_id tidak ditemukan di tmmst.m_emp (FK lintas-DB)';
    END IF;
END */;;
