--
-- Table structure for table `emp_history`
--

DROP TABLE IF EXISTS `emp_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `emp_history` (
  `employee_id` bigint unsigned NOT NULL DEFAULT '0',
  `employee_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nomor Induk Pegawai',
  `device_pin` int unsigned DEFAULT NULL COMMENT 'Nomor pin yang ada di fingerspot',
  `full_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` tinyint unsigned DEFAULT '1' COMMENT 'active atau tidak',
  `gender` tinyint unsigned DEFAULT NULL,
  `hire_date` date DEFAULT NULL,
  `birth_date` date DEFAULT NULL,
  `resign_date` date DEFAULT NULL,
  `retire_date` date DEFAULT NULL,
  `emp_type_id` bigint unsigned DEFAULT NULL COMMENT 'Link to emp_type',
  `emp_level` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Link to emp_level',
  `religion` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `marital_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone_number` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `photo_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `default_shift_id` int DEFAULT NULL COMMENT 'Link to m_shift',
  `payroll_cycle` enum('WEEKLY','MONTHLY') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'MONTHLY',
  `payroll_method` enum('TRANSFER','CASH') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bank_account_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'no rekening',
  `bank_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'nama bank',
  `stat_confirm` tinyint unsigned DEFAULT '0',
  `current_department_id` bigint unsigned DEFAULT NULL,
  `current_section_id` bigint unsigned DEFAULT NULL,
  `current_position_id` bigint unsigned DEFAULT NULL,
  `login` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
